/**
 * Status and categorical hues are themed per role (src/styles/status-colors.css,
 * generated by scripts/gen-status-colors.mjs). Light surfaces and borders are
 * Tailwind's own palette, untouched; light type is Tailwind's too, except the
 * shades the app uses for type that fail AA, which are darkened; dark-mode type
 * clears WCAG AA on the dark surfaces.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { describe, it, expect } from 'vitest';
import colors from 'tailwindcss/colors';

const CSS = readFileSync(path.resolve(__dirname, '../../styles/status-colors.css'), 'utf8');
const HUES = ['red', 'amber', 'green', 'emerald', 'blue', 'sky', 'zinc'] as const;
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;

function block(selector: string): Record<string, number[]> {
  const body = CSS.split(`${selector} {`)[1].split('}')[0];
  return Object.fromEntries([...body.matchAll(/(--[\w-]+): (\d+) (\d+) (\d+);/g)].map((m) => [m[1], [+m[2], +m[3], +m[4]]]));
}

const hexRgb = (hex: string) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));

/** Light shades the app uses for type (4.5:1) or only for icons (3:1) that Tailwind's value fails. */
const LIGHT_TYPE = ['amber-600', 'green-600', 'red-500', 'red-600'];
const LIGHT_ICON = ['amber-500', 'green-500'];
const LIGHT_GROUNDS = { paper: '#ffffff', bg: '#fafaf7', sand: '#f4f5ef' };

function contrast(a: number[], b: number[]) {
  const lum = (c: number[]) => {
    const [r, g, bl] = c.map((v) => {
      const x = v / 255;
      return x <= 0.03928 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * r + 0.7152 * g + 0.0722 * bl;
  };
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

describe('status colours', () => {
  const light = block(':root');
  const dark = block('html.dark');

  it.each(HUES)('%s: surfaces, borders and passing type in light are exactly Tailwind’s value', (hue) => {
    for (const shade of SHADES) {
      const want = hexRgb(colors[hue][shade]);
      for (const role of ['-bg', '-line']) expect(light[`--st-${hue}-${shade}${role}`], `${hue}-${shade}${role}`).toEqual(want);
      const key = `${hue}-${shade}`;
      if (!LIGHT_TYPE.includes(key) && !LIGHT_ICON.includes(key)) expect(light[`--st-${key}`], key).toEqual(want);
    }
  });

  it.each([...LIGHT_TYPE.map((k) => [k, 4.5] as const), ...LIGHT_ICON.map((k) => [k, 3] as const)])(
    'light %s reads at %s:1 on paper, bg, sand and its own -50 chip',
    (key, floor) => {
      const hue = key.split('-')[0] as (typeof HUES)[number];
      const fg = light[`--st-${key}`];
      const grounds = { ...LIGHT_GROUNDS, [`${hue}-50`]: colors[hue][50] };
      for (const [name, ground] of Object.entries(grounds)) {
        expect(contrast(fg, hexRgb(ground)), `${key} on ${name}`).toBeGreaterThanOrEqual(floor);
      }
    },
  );

  it.each(HUES)('%s: dark type from 500 up reads on the dark paper and on its own pale chip', (hue) => {
    const paper = hexRgb('#20241f');
    for (const shade of SHADES.filter((s) => s >= 500)) {
      const fg = dark[`--st-${hue}-${shade}`];
      expect(contrast(fg, paper), `${hue}-${shade} on paper`).toBeGreaterThanOrEqual(4.5);
      expect(contrast(fg, dark[`--st-${hue}-50-bg`]), `${hue}-${shade} on ${hue}-50`).toBeGreaterThanOrEqual(4.5);
    }
  });

  it('patches no Tailwind utility after the fact', () => {
    expect(CSS).not.toMatch(/\.text-white/);
  });
});

/**
 * A status badge with type on it uses a fill token and its paired on-fill
 * token, so the pair is designed (and checked) together in both themes rather
 * than a Tailwind fill meeting a hard-coded white.
 */
describe('status fills', () => {
  const INDEX = readFileSync(path.resolve(__dirname, '../../index.css'), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const tokens = (selector: string) => {
    const body = INDEX.match(new RegExp(`(?:^|\\s)${selector.replace('.', '\\.')}\\s*\\{([^}]*)\\}`))?.[1] ?? '';
    return Object.fromEntries([...body.matchAll(/(--[\w-]+)\s*:\s*(#[0-9a-f]{6})\s*;/gi)].map((m) => [m[1], m[2]]));
  };

  it.each(['ok', 'warn', 'bad'])('--%s-fill carries its on-fill token at AA in light and dark', (status) => {
    for (const selector of [':root', 'html.dark']) {
      const t = tokens(selector);
      const fill = t[`--${status}-fill`];
      const on = t[`--on-${status}-fill`];
      expect(fill && on, `${selector} defines --${status}-fill and --on-${status}-fill`).toBeTruthy();
      expect(contrast(hexRgb(on), hexRgb(fill)), `${selector} ${status}`).toBeGreaterThanOrEqual(4.5);
    }
  });

  it('no status fill is paired with a hard-coded white (hover and opacity variants included)', () => {
    const SRC = path.resolve(__dirname, '../..');
    const walk = (d: string): string[] =>
      readdirSync(d).flatMap((n) => {
        const f = path.join(d, n);
        return statSync(f).isDirectory() ? walk(f) : /\.tsx?$/.test(n) && !/\.test\./.test(n) ? [f] : [];
      });
    // A Tailwind status fill, a status type colour used as a fill, or a fill token meant for its on-fill pair.
    const FILL = /\bbg-(?:(?:red|amber|green|emerald)-\d{2,3}|\[var\(--(?:ok|warn|bad)-(?:fg|fill)\)\])/;
    const hits = walk(SRC).flatMap((f) =>
      readFileSync(f, 'utf8')
        .split('\n')
        .flatMap((line, i) => (FILL.test(line) && /\btext-white\b/.test(line) ? [`${path.relative(SRC, f)}:${i + 1}`] : [])),
    );
    expect(hits).toEqual([]);
  });
});
